mapper.select:

SELECT

FROM biz_event_record


    AND business_type = #{businessType}


    AND business_sub_type = #{businessSubType}


    AND business_id = #{businessId}


    AND business_institute_id = #{businessInstituteId}


    AND operator_id = #{operatorId}


    AND token = #{token,jdbcType=VARCHAR}


    AND operator_institute_id = #{operatorInstituteId}


    AND operation_type = #{operationType,jdbcType=CHAR}


    AND u.create_time BETWEEN #{operationTimeStart,jdbcType=TIMESTAMP} AND #{operationTimeEnd,jdbcType=TIMESTAMP}


order by operation_time desc
